define('taoTestRunnerPlugins/runner/plugins/content/answerCache',['util/namespace', 'taoTests/runner/plugin', 'taoQtiTest/runner/helpers/currentItem'], function (namespaceHelper, pluginFactory, currentItem) {
  'use strict';
  return pluginFactory({
    name: 'answerCache',
    init() {
      var testRunner = this.getTestRunner();
      return testRunner.getPluginStore(this.getName()).then(store => {
        this.storage = store;
        testRunner.after('renderitem', () => {
          var itemRunner = testRunner.itemRunner;
          var testContext = testRunner.getTestContext();
          var key = "".concat(testContext.itemIdentifier, "#").concat(testContext.attempt);
          var {
            allAttempts
          } = this.getConfig();
          testRunner.on(namespaceHelper.namespaceAll('loaditem finish', this.getName()), () => {
            testRunner.off(".".concat(this.getName()));
            return this.storage.clear();
          });
          if (itemRunner && (allAttempts || !currentItem.isAnswered(testRunner))) {
            itemRunner.off(".".concat(this.getName())).on("responsechange.".concat(this.getName()), () => {
              this.storage.setItem(key, itemRunner.getState());
            });
            return this.storage.getItem(key).then(state => {
              if (state) {
                itemRunner.setState(state);
              }
            });
          }
        });
      });
    }
  });
});
