define('taoTestRunnerPlugins/runner/plugins/security/preventCopy',['lodash', 'module', 'util/shortcut', 'taoTests/runner/plugin'], function (_, module, shortcutHelper, pluginFactory) {
  'use strict';
  var allShortcuts = [{
    platform: 'mac',
    key: 'Meta+X',
    label: 'Cmd+X'
  }, {
    platform: 'mac',
    key: 'Meta+C',
    label: 'Cmd+C'
  }, {
    platform: 'mac',
    key: 'Meta+V',
    label: 'Cmd+V'
  }, {
    platform: 'win',
    key: 'Ctrl+X',
    label: 'Ctrl+X'
  }, {
    platform: 'win',
    key: 'Ctrl+C',
    label: 'Ctrl+C'
  }, {
    platform: 'win',
    key: 'Ctrl+V',
    label: 'Ctrl+V'
  }];
  var shortcuts = {};
  var platform = navigator.platform.indexOf('Mac') < 0 ? 'win' : 'mac';
  var defaultConfig = {
    debounceDelay: 500
  };
  var config = _.defaults(module.config() || {}, defaultConfig);
  _.forEach(allShortcuts, function (shortcut) {
    if (shortcut.platform.indexOf(platform) >= 0) {
      shortcuts[toKeyCode(shortcut.key)] = shortcut;
    }
  });
  function registerEvent(target, eventName, listener) {
    if (target.addEventListener) {
      target.addEventListener(eventName, listener, false);
    } else if (target.attachEvent) {
      target.attachEvent('on' + eventName, listener);
    } else {
      target['on' + eventName] = listener;
    }
  }
  function unregisterEvent(target, eventName, listener) {
    if (target.removeEventListener) {
      target.removeEventListener(eventName, listener, false);
    } else if (target.detachEvent) {
      target.detachEvent('on' + eventName, listener);
    } else {
      target['on' + eventName] = null;
    }
  }
  function toKeyCode(combination) {
    var keys = combination.split('+');
    var keyCode = 0;
    _.forEach(keys, function (key) {
      switch (key) {
        case 'Ctrl':
        case 'Meta':
          keyCode += 1114112;
          break;
        default:
          if (key.length === 1) {
            keyCode += key.toUpperCase().charCodeAt(0);
          }
      }
    });
    return keyCode;
  }
  return pluginFactory({
    name: 'preventCopy',
    init: function init() {},
    install: function install() {
      var testRunner = this.getTestRunner();
      var prohibitedKeyFunc;
      var prohibitedKeyDebounce;
      var isIe = typeof window.clipboardData !== 'undefined';
      function setUpIframeEvents() {
        var editors = window.CKEDITOR && window.CKEDITOR.instances || [];
        _.forEach(editors, function (editor) {
          editor.on('key', function (e) {
            var keyCode = e.data.keyCode;
            if (keyCode & CKEDITOR.SHIFT) {
              keyCode -= CKEDITOR.SHIFT;
            }
            if (keyCode & CKEDITOR.ALT) {
              keyCode -= CKEDITOR.ALT;
            }
            if (shortcuts[keyCode]) {
              e.cancel();
            }
          });
          var cutButton = editor.container.find('.cke_button__cut').$;
          if (cutButton.length) {
            $(cutButton[0]).closest('.cke_toolgroup').remove();
          }
        });
      }
      function replaceSelection(target, newValue) {
        var oldValue = target.value.toString().substring(target.selectionStart, target.selectionEnd);
        var caretPosition = target.selectionStart;
        var textBegin = target.value.substring(0, caretPosition);
        var textEnd = target.value.substring(caretPosition + oldValue.length, target.value.length);
        target.value = textBegin + newValue + textEnd;
        target.selectionStart = caretPosition + newValue.length;
        target.selectionEnd = caretPosition + newValue.length;
        target.focus();
      }
      function onCopyCut(event) {
        var target = $(event.target).closest('textarea, input, [contenteditable]')[0];
        if (target) {
          var $target = $(target);
          if ($target.hasClass('allow-copy')) {
            return;
          }
          var text = target.value.toString().substring(target.selectionStart, target.selectionEnd);
          if (isIe) {
            window.clipboardData.setData('Text', '');
          } else {
            event.clipboardData.setData('text/plain', '');
          }
          if (event.type === 'cut') {
            replaceSelection(target, '');
          }
          $target.attr('data-clipboard', text);
        } else {
          event.stopPropagation();
          testRunner.trigger('prohibited-key', event.type);
        }
        event.preventDefault();
      }
      function onPaste(event) {
        event.preventDefault();
        var target = $(event.target).closest('textarea, input, [contenteditable]')[0];
        if (target) {
          var text = $(target).attr('data-clipboard') || '';
          replaceSelection(target, text);
        } else {
          event.stopPropagation();
          testRunner.trigger('prohibited-key', event.type);
        }
      }
      registerEvent(window, 'copy', onCopyCut);
      registerEvent(window, 'cut', onCopyCut);
      registerEvent(window, 'paste', onPaste);
      _.forEach(shortcuts, function (shortcut) {
        prohibitedKeyFunc = function prohibitedKeyFunc(event) {
          if (!$(event.target).closest(':input').length) {
            testRunner.trigger('prohibited-key', shortcut.label);
          }
        };
        prohibitedKeyDebounce = _.debounce(prohibitedKeyFunc, config.debounceDelay, {
          leading: true,
          trailing: false
        });
        shortcutHelper.add(shortcut.key, prohibitedKeyDebounce, {
          avoidInput: true
        });
      });
      testRunner.on('renderitem', function () {
        setUpIframeEvents();
        testRunner.getAreaBroker().getContentArea().find('textarea, input, [contenteditable]').attr('data-clipboard', '');
      }).on('destroy', function () {
        unregisterEvent(window, 'copy', onCopyCut);
        unregisterEvent(window, 'cut', onCopyCut);
        unregisterEvent(window, 'paste', onPaste);
        _.forEach(shortcuts, function (shortcut) {
          shortcutHelper.remove(shortcut.key);
        });
      });
    }
  });
});
