define('taoTestRunnerPlugins/runner/plugins/security/autoPause',['i18n', 'taoTests/runner/plugin'], function (__, pluginFactory) {
  'use strict';
  var pauseMessage = 'You are encountering a connectivity loss. The test has been suspended.';
  return pluginFactory({
    name: 'autoPause',
    init: function init() {
      var testRunner = this.getTestRunner();
      var paused = false;
      testRunner.on('disconnect', function () {
        if (!paused) {
          paused = true;
          testRunner.trigger('disconnectpause').trigger('pause', {
            reasons: {
              category: 'technical',
              subCategory: 'network'
            },
            message: __(pauseMessage),
            originalMessage: pauseMessage
          });
        }
      });
    }
  });
});
