define('taoTestRunnerPlugins/runner/plugins/security/preventScreenshot',['jquery', 'i18n', 'taoTests/runner/plugin'], function ($, __, pluginFactory) {
  'use strict';
  var platform = navigator.platform.indexOf('Mac') < 0 ? 'win' : 'mac';
  var printScreenPauseMessage = 'The assessment has been paused due to an attempt to print screen. Please contact your proctor or administrator to resume your assessment.';
  var isIe = typeof window.clipboardData !== 'undefined';
  var overrideContent = ' ';
  var $body = $('body');
  var blur = () => $body.css('filter', 'blur(20px)');
  var unBlur = () => $body.css('filter', '');
  var triggerCopyEvent = () => {
    if (isIe) {
      document.designMode = 'on';
    }
    if (document.execCommand && document.queryCommandSupported('copy')) {
      document.execCommand('copy');
    }
    if (isIe) {
      document.designMode = 'off';
    }
  };
  var focusOnFakeInput = () => {
    var input = document.createElement('input');
    input.setAttribute('value', overrideContent);
    input.classList.add('allow-copy');
    document.body.appendChild(input);
    input.select();
    triggerCopyEvent();
    document.body.removeChild(input);
  };
  var isPauseForced = testRunner => {
    var {
      securePauseStateRequired
    } = testRunner.getTestContext();
    var {
      sectionPause,
      proctored
    } = testRunner.getOptions();
    return typeof sectionPause === 'boolean' ? sectionPause : proctored || securePauseStateRequired;
  };
  var preventScreenshot = testRunner => {
    focusOnFakeInput();
    if (isPauseForced(testRunner)) {
      testRunner.trigger('pause', {
        message: __(printScreenPauseMessage),
        reasons: {
          category: 'examinee',
          subCategory: 'behaviour'
        },
        originalMessage: printScreenPauseMessage
      });
    }
  };
  return pluginFactory({
    name: 'preventScreenshot',
    init: function init() {},
    install: function install() {
      var testRunner = this.getTestRunner();
      if (platform === 'mac') {
        $(window).on("keydown.".concat(this.getName()), e => {
          if (e.metaKey && e.shiftKey) {
            blur();
          }
        }).on("keyup.".concat(this.getName()), e => {
          if (!e.metaKey || !e.shiftKey) {
            unBlur();
          }
        }).on('focus', unBlur).on('click', unBlur);
      } else if (platform === 'win') {
        $(window).on("keyup.".concat(this.getName()), e => {
          if (e.key === 'PrintScreen') {
            testRunner.trigger('prohibited-key', 'PrintScreen');
            preventScreenshot(testRunner);
          }
        });
      }
    },
    destroy: function destroy() {
      $(window).off('.' + this.getName());
    }
  });
});
