define('taoTestRunnerPlugins/runner/plugins/security/watermark',['jquery', 'lodash', 'i18n', 'taoTests/runner/plugin', 'context', 'taoQtiTest/runner/helpers/map', 'core/digest', 'ui/dialog', 'taoQtiTest/runner/config/states', 'tpl!taoTestRunnerPlugins/runner/plugins/security/templates/watermarkCirclePath', 'css!taoTestRunnerPlugins/runner/plugins/security/css/watermark'], function ($, _, __, pluginFactory, context, mapHelper, digest, dialog, states, watermarkCirclePathTpl) {
  'use strict';

  var defaultConfig = {
    hashAlgorithm: 'SHA-1',
    type: 'horizontal',
    layer: 'background',
    style: '',
    containerStyle: '',
    textPartLength: 10,
    separatorsLength: 3,
    unlock: {
      enabled: false,
      triggerWord: 'WMK',
      algorithm: 'SHA-512',
      hash: ''
    },
    configsByCategory: {}
  };
  var watermarkTypes = {
    horizontal: 'horizontal',
    diagonal: 'diagonal',
    circle: 'circle'
  };
  function addMultikeyShortcut(triggerWord, action, abortController, freeSpaceTargets) {
    var maxTimeBetweenKeys = 3 * 1000;
    freeSpaceTargets = [document.body, ...(freeSpaceTargets || [])];
    var typedWord = '';
    var prevTimestamp = Date.now();
    var handleKeyup = e => {
      if (freeSpaceTargets.includes(e.target)) {
        var isLetterKey = e.key.length === 1;
        if (isLetterKey) {
          var timestamp = Date.now();
          if (timestamp - prevTimestamp > maxTimeBetweenKeys) {
            typedWord = '';
          }
          prevTimestamp = timestamp;
          typedWord = typedWord + e.key;
          if (typedWord.length > triggerWord.length) {
            typedWord = typedWord.substring(1);
          }
          if (typedWord === triggerWord) {
            typedWord = '';
            action();
          }
        }
      }
    };
    freeSpaceTargets[0].addEventListener('keyup', handleKeyup, {
      signal: abortController.signal
    });
  }
  return pluginFactory({
    name: 'watermark',
    install: function install() {
      this.pluginConfig = {};
      this.$watermark = null;
      this.abortController = null;
      this.isNotUnlocked = true;
      this.getIsEnabledByCategory = () => {
        var testRunner = this.getTestRunner();
        var testMap = testRunner.getTestMap();
        var itemIdentifier = testRunner.getTestContext().itemIdentifier;
        var enabledByCategory = false;
        if (this.getConfig() && this.getConfig().configsByCategory) {
          for (var categorySuffix of Object.keys(this.getConfig().configsByCategory)) {
            var category = "".concat(this.getName(), "-").concat(categorySuffix);
            if (mapHelper.hasItemCategory(testMap, itemIdentifier, category, true)) {
              this.pluginConfig = _.merge({}, defaultConfig, this.getConfig(), _.omit(this.getConfig().configsByCategory[categorySuffix], ['unlock']));
              enabledByCategory = true;
              break;
            }
          }
        }
        if (!enabledByCategory) {
          var _category = this.getName();
          if (mapHelper.hasItemCategory(testMap, itemIdentifier, _category, true)) {
            this.pluginConfig = _.merge({}, defaultConfig, this.getConfig());
            enabledByCategory = true;
          }
        }
        return enabledByCategory;
      };
      var textHash;
      var textHashAlgorithm;
      this.getTextHash = () => {
        var text = context.currentUser && context.currentUser.login || 'anonymous';
        var algorithm = this.pluginConfig.hashAlgorithm;
        if (textHash && textHashAlgorithm === algorithm) {
          return Promise.resolve(textHash);
        }
        return digest(text, algorithm).then(hash => {
          textHash = hash;
          textHashAlgorithm = algorithm;
          return textHash;
        });
      };
      this.getText = () => this.getTextHash().then(userHash => {
        var textPartLength = Math.min(this.pluginConfig.textPartLength, userHash.length);
        var separatorsLength = this.pluginConfig.separatorsLength;
        var str = '';
        for (var idx = 0; idx < userHash.length - textPartLength + 1; idx = idx + textPartLength) {
          str += userHash.slice(idx, idx + textPartLength);
          str += ' '.repeat(separatorsLength);
        }
        if (!separatorsLength) {
          str += ' ';
        }
        return str;
      });
      this.renderText = ($watermarkContent, text, itemScale) => {
        for (var i = 0; i < 10; i++) {
          var actualHeight = $watermarkContent.get(0).offsetHeight;
          var expectedHeight = this.$watermark.get(0).offsetHeight + (this.pluginConfig.type === watermarkTypes.horizontal ? 0 : this.$watermark.get(0).offsetWidth);
          if (actualHeight < expectedHeight) {
            var repeatedText = text.repeat(200 / itemScale);
            $watermarkContent.get(0).textContent += repeatedText;
          } else {
            break;
          }
        }
      };
      this.renderCircle = ($watermarkContent, text) => {
        $watermarkContent.html('');
        var contentEl = $watermarkContent.get(0);
        var boxSize = Math.trunc(Math.min(contentEl.offsetWidth, contentEl.offsetHeight));
        var fontSizePropVal = getComputedStyle(contentEl).getPropertyValue('font-size');
        var halfOfBoxSize = Math.trunc(boxSize / 2);
        var fontSize = parseInt(fontSizePropVal) || 10;
        var radius = halfOfBoxSize - fontSize;
        var repeatedText = text.repeat(Math.trunc(3.15 * 2 * radius / text.length / (fontSize / 4)));
        $watermarkContent.html(watermarkCirclePathTpl({
          boxSize,
          repeatedText,
          s: halfOfBoxSize,
          f: fontSize,
          r: radius,
          sr: halfOfBoxSize + radius
        }));
      };
      var validateUnlock = val => digest(val, this.pluginConfig.unlock.algorithm).then(hash => hash === this.pluginConfig.unlock.hash);
      var doUnlock = () => {
        this.isNotUnlocked = !this.isNotUnlocked;
        if (this.getIsEnabledByCategory() && this.isNotUnlocked) {
          this.show();
        } else {
          this.hide();
        }
      };
      this.showUnlockDialog = () => {
        this.removeUnlockListener();
        var appendToEl = this.getAreaBroker().getContainer().find('.content-wrapper').get(0);
        var label = this.isNotUnlocked ? __('To hide watermark, type keyword') : __('To show watermark, type keyword');
        var dialogTpl = "<label>".concat(label, "<input autocomplete=\"off\" class=\"tao-wmark-input\" style=\"-webkit-text-security:disc\" /></label>");
        var dlg = dialog({
          autoRender: true,
          autoDestroy: true,
          content: dialogTpl,
          width: 300,
          buttons: [],
          renderTo: appendToEl
        });
        dlg.on('closed.modal', () => {
          this.addUnlockListener();
        });
        var submit = val => validateUnlock(val).then(valid => {
          if (valid) {
            doUnlock();
          }
        });
        var $input = dlg.getDom().find('.tao-wmark-input');
        $input.on('copy', e => {
          e.preventDefault();
        }).on('keydown', e => {
          e.stopPropagation();
          if (e.key === 'Enter') {
            $input.off('change');
            submit(e.target.value);
            dlg.hide();
          } else if (e.key === 'Escape') {
            dlg.hide();
          }
        }).on('change', e => {
          submit(e.target.value);
          dlg.hide();
        }).focus();
      };
      this.addUnlockListener = () => {
        this.abortController = new AbortController();
        addMultikeyShortcut(this.pluginConfig.unlock.triggerWord, () => this.showUnlockDialog(), this.abortController, [this.getAreaBroker().getContainer().find('.content-wrapper').get(0)]);
      };
      this.removeUnlockListener = () => {
        if (this.abortController) {
          this.abortController.abort();
        }
      };
      this.itemHasOverlay = () => {
        var testContext = this.getTestRunner().getTestContext();
        return testContext.itemSessionState === states.itemSession.closed;
      };
    },
    init: function init() {
      var testRunner = this.getTestRunner();
      this.pluginConfig = _.merge({}, defaultConfig, this.getConfig());
      testRunner.on("renderitem.".concat(this.getName()), () => {
        if (this.getIsEnabledByCategory()) {
          if (this.isNotUnlocked) {
            this.hide();
            this.show();
          }
          if (this.pluginConfig.unlock && this.pluginConfig.unlock.enabled && this.pluginConfig.unlock.triggerWord && this.pluginConfig.unlock.hash) {
            this.addUnlockListener();
          }
        }
      }).on("unloaditem.".concat(this.getName()), () => {
        this.hide();
        this.removeUnlockListener();
      }).after("tool-zoomout.".concat(this.getName(), " tool-zoomin.").concat(this.getName()), () => {
        if (this.getIsEnabledByCategory() && this.isNotUnlocked) {
          this.hide();
          this.show();
        }
      });
    },
    show: function show() {
      var $coverArea = this.getAreaBroker().getContainer().find('.content-wrapper');
      var $appendTo = this.getTestRunner().getAreaBroker().getContentArea();
      var classesStr = ['tao-wmark', this.pluginConfig.type, this.pluginConfig.layer, this.itemHasOverlay() ? 'overlayed' : ''].filter(Boolean).join(' ');
      this.$watermark = $("<div class=\"".concat(classesStr, "\" aria-hidden=\"true\"><div></div></div>"));
      var $watermarkContent = this.$watermark.children().first();
      if (this.pluginConfig.style) {
        $watermarkContent.attr('style', this.pluginConfig.style);
      }
      $appendTo.prepend(this.$watermark);
      var originalContentStyle = $watermarkContent.attr('style') || '';
      var computedContentStyle = getComputedStyle($watermarkContent.get(0));
      var scalableComputedContentStyle = ['font-size', 'line-height', 'letter-spacing'].reduce((acc, prop) => {
        acc[prop] = computedContentStyle.getPropertyValue(prop);
        return acc;
      }, {});
      this.getText().then(text => {
        this.throttledResizeCallback = _.throttle(() => requestAnimationFrame(() => {
          var containerRect = $coverArea.get(0).getBoundingClientRect();
          var itemScale = Math.max(0.4, parseFloat(computedContentStyle.getPropertyValue('--tool-zoom-level')) || 1);
          var containerBox = {
            left: containerRect.left,
            width: containerRect.width,
            top: containerRect.top,
            height: containerRect.height
          };
          var style = ['left', 'width', 'top', 'height'].map(prop => "".concat(prop, ": ").concat(Math.round(containerBox[prop]), "px")).join(';');
          if (this.pluginConfig.containerStyle) {
            style += ";".concat(this.pluginConfig.containerStyle);
          }
          this.$watermark.attr('style', style);
          if (Math.abs(itemScale - 1) > 0.01) {
            var scaledContentStyle = Object.keys(scalableComputedContentStyle).map(prop => "".concat(prop, ": calc(").concat(itemScale, " * ").concat(scalableComputedContentStyle[prop], ")")).join(';');
            $watermarkContent.attr('style', "".concat(originalContentStyle, ";").concat(scaledContentStyle));
          }
          if (this.pluginConfig.type === watermarkTypes.circle) {
            this.renderCircle($watermarkContent, text);
          } else {
            this.renderText($watermarkContent, text, itemScale);
          }
        }), 100);
        this.resizeObserver = new ResizeObserver(this.throttledResizeCallback);
        this.resizeObserver.observe($coverArea.get(0));
      });
    },
    hide: function hide() {
      if (this.throttledResizeCallback) {
        this.throttledResizeCallback.cancel();
        this.throttledResizeCallback = null;
      }
      if (this.resizeObserver) {
        this.resizeObserver.disconnect();
        this.resizeObserver = null;
      }
      if (this.$watermark) {
        this.$watermark.remove();
        this.$watermark = null;
      }
    },
    destroy: function destroy() {
      this.removeUnlockListener();
      this.getTestRunner().off(this.getName());
      this.hide();
    }
  });
});
